import sys


def main() -> None:
    data = sys.stdin.buffer.read().split()
    m = int(data[0])
    n = int(data[1])
    rows = []
    p = 2
    for _ in range(m):
        rows.append(data[p:p + n])
        p += n
    base = rows[0]
    odd = -1
    two = False
    for i in range(1, m):
        if rows[i] != base:
            if odd == -1:
                odd = i
            else:
                two = True
                break
    if two:
        other = rows[1]
        for j in range(n):
            if other[j] != base[j]:
                sys.stdout.write("1 %d %s\n" % (j + 1, other[j].decode()))
                return
    else:
        other = rows[odd]
        for j in range(n):
            if other[j] != base[j]:
                sys.stdout.write("%d %d %s\n" % (odd + 1, j + 1, base[j].decode()))
                return


main()

